{"command": "cd /workspace/vllm-project/vllm && python - <<'PY'
import torch
from vllm.model_executor.layers.rotary_embedding.mrope import apply_interleaved_rope
for sections in ([2,2,2],[4,3,1],[1,1,4],[8,6,2]):
    half=sum(sections)
    x=torch.zeros(3,1,half)
    x[0,0]=1000+torch.arange(half)
    x[1,0]=2000+torch.arange(half)
    x[2,0]=3000+torch.arange(half)
    y=apply_interleaved_rope(x, list(sections))[0,0]
    got=[]
    for i in range(half):
        if i%3==0 and i<sections[0]*3:
            got.append(1000+i)
        elif i%3==1 and i<sections[1]*3:
            got.append(2000+i)
        elif i%3==2 and i<sections[2]*3:
            got.append(3000+i)
        else:
            got.append(1000+i)
    got=torch.tensor(got, dtype=y.dtype)
    print(sections, torch.equal(y, got), y.tolist(), got.tolist())
PY"}

