from pathlib import Path
import json
text = Path('vllm/model_executor/layers/rotary_embedding/mrope.py').read_text().splitlines()
start = next(i for i,l in enumerate(text) if l.startswith('def _triton_mrope_forward('))
end = next(i for i,l in enumerate(text[start+1:], start+1) if l.startswith('def triton_mrope('))
body = '\n'.join(text[start:end]).rstrip()
out = {
  'vllm/model_executor/layers/rotary_embedding/mrope.py': {
    '_triton_mrope_forward': body
  }
}
Path('/prediction.json').write_text(json.dumps(out, indent=4))
print('wrote /prediction.json')
PY"}

